tag: Tag,
start: ByteOffset,
end: ByteOffset,

const Token = @This();

pub const ByteOffset = enum(u32) { _ };

pub const Tag = enum {
    invalid,

    // 12.4 Comments
    // https://tc39.es/ecma262/#sec-comments
    line_comment,
    multiline_comment,

    // B.1.1 HTML-like Comments
    // https://tc39.es/ecma262/#sec-html-like-comments
    html_open_comment,
    html_close_comment,

    // 12.5 Hashbang Comments
    // https://tc39.es/ecma262/#sec-hashbang
    hashbang_comment,

    // 12.7 Names and Keywords
    // https://tc39.es/ecma262/#sec-names-and-keywords
    identifier,
    private_identifier,
    keyword_await,
    keyword_break,
    keyword_case,
    keyword_catch,
    keyword_class,
    keyword_const,
    keyword_continue,
    keyword_debugger,
    keyword_default,
    keyword_delete,
    keyword_do,
    keyword_else,
    keyword_enum,
    keyword_export,
    keyword_extends,
    keyword_false,
    keyword_finally,
    keyword_for,
    keyword_function,
    keyword_if,
    keyword_import,
    keyword_in,
    keyword_instanceof,
    keyword_new,
    keyword_null,
    keyword_return,
    keyword_super,
    keyword_switch,
    keyword_this,
    keyword_throw,
    keyword_true,
    keyword_try,
    keyword_typeof,
    keyword_var,
    keyword_void,
    keyword_while,
    keyword_with,
    keyword_yield,

    // 12.8 Punctuators
    // https://tc39.es/ecma262/#sec-punctuators
    question_mark_period,
    left_curly_bracket,
    right_curly_bracket,
    left_parenthesis,
    right_parenthesis,
    left_square_bracket,
    right_square_bracket,
    period,
    ellipsis,
    semicolon,
    comma,
    less_than,
    greater_than,
    less_than_equals,
    greater_than_equals,
    double_equals,
    exclamation_mark_equals,
    triple_equals,
    exclamation_mark_double_equals,
    plus,
    minus,
    asterisk,
    percent,
    double_asterisk,
    double_plus,
    double_minus,
    double_less_than,
    double_greater_than,
    triple_greater_than,
    ampersand,
    pipe,
    caret,
    exclamation_mark,
    tilde,
    double_ampersand,
    double_pipe,
    double_question_mark,
    question_mark,
    colon,
    equals,
    plus_equals,
    minus_equals,
    asterisk_equals,
    percent_equals,
    double_asterisk_equals,
    double_less_than_equals,
    double_greater_than_equals,
    triple_greater_than_equals,
    ampersand_equals,
    pipe_equals,
    caret_equals,
    double_ampersand_equals,
    double_pipe_equals,
    double_question_mark_equals,
    equals_greater_than,
    slash,
    slash_equals,

    // 12.9 Literals
    // https://tc39.es/ecma262/#sec-ecmascript-language-lexical-grammar-literals
    number_literal,
    bigint_literal,
    string_literal,
    regexp_literal,
    template_literal,
    template_literal_head,
    template_literal_middle,
    template_literal_tail,

    pub fn beforeExpr(tag: Tag) bool {
        return switch (tag) {
            .identifier,
            .private_identifier,
            .keyword_this,
            .keyword_super,
            .keyword_true,
            .keyword_false,
            .keyword_null,
            .right_curly_bracket,
            .right_parenthesis,
            .right_square_bracket,
            .period,
            .question_mark_period,
            .double_minus,
            .double_plus,
            .bigint_literal,
            .number_literal,
            .string_literal,
            .regexp_literal,
            .template_literal,
            .template_literal_tail,
            => false,
            else => true,
        };
    }

    pub fn isKeyword(tag: Tag) bool {
        return switch (tag) {
            .keyword_await,
            .keyword_break,
            .keyword_case,
            .keyword_catch,
            .keyword_class,
            .keyword_const,
            .keyword_continue,
            .keyword_debugger,
            .keyword_default,
            .keyword_delete,
            .keyword_do,
            .keyword_else,
            .keyword_enum,
            .keyword_export,
            .keyword_extends,
            .keyword_false,
            .keyword_finally,
            .keyword_for,
            .keyword_function,
            .keyword_if,
            .keyword_import,
            .keyword_in,
            .keyword_instanceof,
            .keyword_new,
            .keyword_null,
            .keyword_return,
            .keyword_super,
            .keyword_switch,
            .keyword_this,
            .keyword_throw,
            .keyword_true,
            .keyword_try,
            .keyword_typeof,
            .keyword_var,
            .keyword_void,
            .keyword_while,
            .keyword_with,
            .keyword_yield,
            => true,
            else => false,
        };
    }
};

pub fn text(token: Token, source: []const u8) []const u8 {
    return source[@backingInt(token.start)..@backingInt(token.end)];
}
